/**
 * @deepseek-ai/dsh-tools overlay (minimal).
 *
 * Honest overlay: the real package (packages/core/tools) is a ~2000-line
 * ToolRegistry service whose value deps pull a peer chain. What the
 * agent-loop proof requires is only the scheduler boundary identities the
 * loop's tool-calls.ts imports as VALUES: the {@link TOOL_RUNTIME_SCHEDULER}
 * unique symbol (the real symbol identity, so a worker-built `ctx.tools`
 * object keyed by this import matches the loop's lookup) and the synthetic
 * abort code. The full ToolExecutionInput / ToolExecutionMode /
 * ToolExecutionResult / ToolRunContext types are type-only and stripped.
 *
 * The real scheduler/executor is NOT included: {@link ctx.tools} is supplied
 * by the dsh-java driver as a stub (see the agent-loop-driver + the Java-side
 * ToolsStub seam) — a real tool registry + executor is a documented NEEDS.
 *
 * @module @deepseek-ai/dsh-tools
 */

/**
 * The unique symbol under which the runtime tool-call scheduler is registered
 * on {@link ctx.tools} (real value: `Symbol('@deepseek-ai/dsh-tools.scheduler')`).
 */
export const TOOL_RUNTIME_SCHEDULER = Symbol('@deepseek-ai/dsh-tools.scheduler')

/** Canonical result code for a call the runtime chose not to start. */
export const TOOL_ABORTED = 'ABORTED'

/** Canonical result code for a call skipped because its step aborted before dispatch. */
export const TOOL_ABORTED_BEFORE_DISPATCH = 'ABORTED_BEFORE_DISPATCH'
